package com.dongwon.sleeptimeline;
import java.util.*;
public class SleepLogicTest {
 static void check(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 static SleepLogic.Event e(long t,int type){return new SleepLogic.Event(t,type,"app");}
 public static void main(String[]args){long base=1000000000L;List<SleepLogic.Event> a=new ArrayList<SleepLogic.Event>();check(SleepLogic.candidates(a,5400000,base).isEmpty(),"Empty history");a.add(e(base,16));check(SleepLogic.candidates(a,5400000,base+36000000).isEmpty(),"Unfinished interval");a.add(e(base+600000,15));a.add(e(base+28800000,18));List<SleepLogic.Gap> g=SleepLogic.candidates(a,5400000,base+28800000);check(g.size()==1&&g.get(0).start==base&&g.get(0).end==base+28800000,"Notification screen on is not unlock");a=Arrays.asList(e(base,16),e(base+3600000,18));check(SleepLogic.candidates(a,5400000,base+3600000).isEmpty(),"Below threshold");a=Arrays.asList(e(base,16),e(base+5400000,18));check(SleepLogic.candidates(a,5400000,base+5400000).size()==1,"Exact threshold");a=Arrays.asList(e(base,16),e(base+100000,26),e(base+28800000,18));check(SleepLogic.candidates(a,5400000,base+28800000).isEmpty(),"Shutdown excluded");a=Arrays.asList(e(base,16),e(base+19*3600000,18));check(SleepLogic.candidates(a,5400000,base+19*3600000).isEmpty(),"Extreme inactivity");check(!SleepLogic.overlaps(1,2,2,3),"Adjacent periods allowed");check(SleepLogic.overlaps(1,3,2,4),"Overlap detected");check(!SleepLogic.valid(base,base-1,base),"Reversed period");check(!SleepLogic.valid(base,base+100000,base),"Future period");a=Arrays.asList(e(base,1),e(base+600000,1),e(base+1800000,16));List<SleepLogic.Session> sessions=SleepLogic.sessions(a,base,base+3600000);check(sessions.size()==1&&sessions.get(0).end-sessions.get(0).start==1800000,"Repeated activity resume preserves usage");System.out.println("PASS: 11 sleep inference and usage checks");}
}
